"use client";

import type { CSSProperties } from "react";
import { Easing, interpolate, useCurrentFrame } from "remotion";

export type KbdShortcutVariant = "light" | "dark";

export type KbdShortcutPosition =
  | "bottom-center"
  | "bottom-left"
  | "bottom-right"
  | "top-center"
  | "top-left"
  | "top-right"
  | "center";

export interface KbdShortcutProps {
  /** Keycap legends — array, or a single string split on spaces / "+", e.g. "⌘ K" or "⌘+K". */
  keys?: string[] | string;
  /** Frame at which the first keycap presses down. Keys stagger 2 frames after each other. */
  pressAt?: number;
  /** Optional caption rendered after the keycaps (e.g. what the shortcut does). */
  label?: string;
  /** Where the overlay sits inside the frame. */
  position?: KbdShortcutPosition;
  /** Frames the keycaps stay fully pressed before releasing. */
  holdFrames?: number;
  /** Frames to fade the whole overlay out after the release. 0 keeps it on screen. */
  exitFade?: number;
  /** Frame at which the overlay pops in. */
  enterAt?: number;
  /** Palette: white keycaps for light scenes, graphite for dark ones. */
  variant?: KbdShortcutVariant;
  /** Keycap legend size in px; every other dimension scales with it. */
  fontSize?: number;
  /** Distance in px from the frame edges for the edge position presets. */
  margin?: number;
  /** Keycap surface override. Defaults per variant. */
  capColor?: string;
  /** 1px keycap border override. Defaults per variant. */
  borderColor?: string;
  /** Legend color override. Defaults per variant. */
  textColor?: string;
  /** Caption color override. Defaults per variant. */
  labelColor?: string;
  speed?: number;
  className?: string;
}

const SANS_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
const MONO_FAMILY =
  "'JetBrains Mono', var(--font-geist-mono), ui-monospace, SFMono-Regular, Menlo, monospace";

/** Frames a single keycap takes to travel down (and back up). */
export const PRESS_FRAMES = 3;
/** Frames between one keycap pressing and the next (chord feel). */
export const PRESS_STAGGER = 2;
/** Frames the entrance pop takes. */
export const ENTER_FRAMES = 12;

/** Per-variant snap-cn palette for the keycaps. */
export const KBD_PALETTES: Record<
  KbdShortcutVariant,
  { cap: string; border: string; text: string; depth: string; label: string }
> = {
  light: {
    cap: "#FFFFFF",
    border: "#E4E7EC",
    text: "#101828",
    depth: "#E4E7EC",
    label: "#667085",
  },
  dark: {
    cap: "#141417",
    border: "#26272B",
    text: "#FAFAFA",
    depth: "#26272B",
    label: "#A1A1AA",
  },
};

/** Flex alignment for each position preset (row container over the full frame). */
export const POSITION_STYLES: Record<
  KbdShortcutPosition,
  {
    justifyContent: CSSProperties["justifyContent"];
    alignItems: CSSProperties["alignItems"];
  }
> = {
  "bottom-center": { justifyContent: "center", alignItems: "flex-end" },
  "bottom-left": { justifyContent: "flex-start", alignItems: "flex-end" },
  "bottom-right": { justifyContent: "flex-end", alignItems: "flex-end" },
  "top-center": { justifyContent: "center", alignItems: "flex-start" },
  "top-left": { justifyContent: "flex-start", alignItems: "flex-start" },
  "top-right": { justifyContent: "flex-end", alignItems: "flex-start" },
  center: { justifyContent: "center", alignItems: "center" },
};

/** Accepts an array or a "+" / whitespace separated string; trims and drops empties. */
export function normalizeKeys(keys: string[] | string): string[] {
  const list = Array.isArray(keys) ? keys : keys.split(/[+\s]+/);
  return list.map((k) => k.trim()).filter((k) => k.length > 0);
}

export interface PressTimings {
  /** Frame the first key starts travelling down. */
  pressAt: number;
  /** Frames between successive key-downs. */
  stagger: number;
  /** Frames for the down (and up) travel of one key. */
  pressFrames: number;
  /** Frames a key stays fully pressed. */
  holdFrames: number;
}

/**
 * Press depth of the keycap at `index`: 0 = resting, 1 = fully pressed.
 * Ramp down over `pressFrames`, hold, ramp back up over `pressFrames`.
 */
export function keyPressDepth(
  frame: number,
  index: number,
  t: PressTimings,
): number {
  const start = t.pressAt + index * t.stagger;
  const downEnd = start + t.pressFrames;
  const holdEnd = downEnd + t.holdFrames;
  const upEnd = holdEnd + t.pressFrames;
  if (frame <= start) return 0;
  if (frame < downEnd) return (frame - start) / t.pressFrames;
  if (frame < holdEnd) return 1;
  if (frame < upEnd) return 1 - (frame - holdEnd) / t.pressFrames;
  return 0;
}

/** Frame at which the last keycap has fully released (exit fade starts here). */
export function pressSequenceEnd(keyCount: number, t: PressTimings): number {
  if (keyCount <= 0) return t.pressAt;
  return (
    t.pressAt + (keyCount - 1) * t.stagger + t.pressFrames * 2 + t.holdFrames
  );
}

/** Overlay opacity for the exit: 1 until `exitStart`, then linear fade over `exitFade` frames. */
export function exitOpacity(
  frame: number,
  exitStart: number,
  exitFade: number,
): number {
  if (exitFade <= 0) return 1;
  if (frame <= exitStart) return 1;
  return Math.max(0, 1 - (frame - exitStart) / exitFade);
}

export function KbdShortcut({
  keys = ["⌘", "K"],
  pressAt = 24,
  label = "",
  position = "bottom-center",
  holdFrames = 18,
  exitFade = 12,
  enterAt = 0,
  variant = "light",
  fontSize = 13,
  margin = 48,
  capColor,
  borderColor,
  textColor,
  labelColor,
  speed = 1,
  className,
}: KbdShortcutProps) {
  const frame = useCurrentFrame() * speed;

  const palette = KBD_PALETTES[variant] ?? KBD_PALETTES.light;
  const cap = capColor ?? palette.cap;
  const hairline = borderColor ?? palette.border;
  const legend = textColor ?? palette.text;
  const caption = labelColor ?? palette.label;

  const keyList = normalizeKeys(keys);
  const timings: PressTimings = {
    pressAt,
    stagger: PRESS_STAGGER,
    pressFrames: PRESS_FRAMES,
    holdFrames,
  };
  const exitStart = pressSequenceEnd(keyList.length, timings) + 4;
  const align = POSITION_STYLES[position] ?? POSITION_STYLES["bottom-center"];

  // Everything scales off the 13px reference so the overlay stays crisp at any size.
  const unit = fontSize / 13;
  const capHeight = Math.round(28 * unit);
  const capRadius = Math.round(6 * unit);
  const depthPx = Math.max(2, Math.round(2 * unit)); // resting bottom-shadow depth
  const travelPx = Math.max(1, Math.round(1 * unit)); // press-down translateY

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        justifyContent: align.justifyContent,
        alignItems: align.alignItems,
        padding: margin,
        pointerEvents: "none",
        fontFamily: SANS_FAMILY,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: Math.round(6 * unit),
          // Entrance pop: fast fade-up, high-damping ease-out, no bounce.
          opacity:
            interpolate(frame, [enterAt, enterAt + ENTER_FRAMES - 4], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }) * exitOpacity(frame, exitStart, exitFade),
          translate: interpolate(
            frame,
            [enterAt, enterAt + ENTER_FRAMES],
            ["0px 8px", "0px 0px"],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            },
          ),
          scale: interpolate(
            frame,
            [enterAt, enterAt + ENTER_FRAMES],
            [0.94, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            },
          ),
        }}
      >
        {keyList.map((key, i) => {
          const depth = keyPressDepth(frame, i, timings);
          return (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: legends may repeat (e.g. ⇧ ⇧)
              key={`${key}-${i}`}
              style={{
                boxSizing: "border-box",
                minWidth: capHeight,
                height: capHeight,
                padding: `0 ${Math.round(8 * unit)}px`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                backgroundColor: cap,
                border: `1px solid ${hairline}`,
                borderRadius: capRadius,
                fontFamily: MONO_FAMILY,
                fontSize,
                fontWeight: 500,
                color: legend,
                lineHeight: 1,
                // Press-down: 1px travel + the bottom depth shadow collapses.
                translate: `0px ${depth * travelPx}px`,
                boxShadow: `inset 0 -${(1 - depth) * depthPx}px 0 ${hairline}, 0 1px 2px rgba(16,24,40,${variant === "light" ? 0.06 : 0.4})`,
              }}
            >
              {key}
            </div>
          );
        })}
        {label ? (
          <div
            style={{
              marginLeft: Math.round(4 * unit),
              fontSize: Math.round(12 * unit),
              fontWeight: 500,
              letterSpacing: "-0.01em",
              color: caption,
            }}
          >
            {label}
          </div>
        ) : null}
      </div>
    </div>
  );
}
